//! Baselines of a VM (ROADMAP 8 and 10, F3): list with label, creation
//! time, verified or not, protected, size, current and in use; summary of
//! the VM's current state (standalone disk or overlay of a baseline);
//! creation, restore and deletion. The view executes nothing: it returns
//! the chosen [`BaselineAction`]; the confirmations and the commands are in
//! `lib.rs`.
//!
//! A baseline is always "a baseline with the VM off", never a snapshot with
//! RAM. Labels are generated by LightVM (`Baseline 3 · 2026-10-11 09:12
//! UTC`): the UI keeps a single text field (the VM name in the wizard).

use std::time::Duration;

use egui::WidgetType;
use lightvm_proto::ipc::{BaselineSummary, StorageOperation, VmSummary};
use lightvm_proto::{BaselineId, ErrorCode, Label, UtcTimestamp, VmState};

use crate::dashboard::{format_bytes, vm_state};
use crate::service::{BaselineList, BaselineOp, BaselineRequest, Failure, RequestStatus};
use crate::theme::{self, Tone};

/// Description under the page title.
pub const DESCRIPTION: &str = "Read-only copies of the VM's disk and UEFI variables, taken with the VM off. Restoring one brings the VM back to that state.";

/// Elapsed time from which the duration of a long operation is shown.
const SHOW_ELAPSED_AFTER: Duration = Duration::from_secs(5);

/// Choice made in the Baselines page.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum BaselineAction {
    /// Back to the Dashboard.
    Back,
    /// Emergency Stop (also cancels a running baseline operation).
    EmergencyStop,
    /// Re-read the VM and its baselines.
    Refresh,
    /// Create a baseline (asks for confirmation).
    Create,
    /// Restore a baseline (asks for confirmation).
    Restore(BaselineId),
    /// Delete a baseline (asks for confirmation).
    Delete(BaselineId),
}

/// What the page needs to know.
#[derive(Clone, Copy, Debug)]
pub struct BaselinesEnv<'a> {
    /// VM.
    pub vm: &'a VmSummary,
    /// Baselines as last read, if requested.
    pub list: Option<&'a BaselineList>,
    /// Last baseline operation requested by the UI, if it concerns this VM.
    pub request: Option<&'a BaselineRequest>,
    /// A baseline operation requested by the UI is waiting for its outcome
    /// (on any VM): only one at a time.
    pub any_pending: bool,
    /// Supervisor connected.
    pub active: bool,
    /// The supervisor can create and restore baselines.
    pub available: bool,
    /// Time since the UI sent the running operation, if it did.
    pub elapsed: Option<Duration>,
}

/// Date and time of a timestamp, to the minute: `2026-10-11 09:12 UTC`.
pub fn format_time(t: UtcTimestamp) -> String {
    let s = t.to_string();
    match (s.get(..10), s.get(11..16)) {
        (Some(d), Some(h)) => format!("{d} {h} UTC"),
        _ => s,
    }
}

/// Label generated for a new baseline: `Baseline N · <date> UTC`, with `N`
/// the first number not used by an existing label.
pub fn auto_label(existing: &[BaselineSummary], now: UtcTimestamp) -> Label {
    let mut n = existing.len() + 1;
    let taken = |n: usize| {
        let prefix = format!("Baseline {n} ");
        existing
            .iter()
            .any(|b| b.label.as_str().starts_with(&prefix) || b.label.as_str() == prefix.trim_end())
    };
    while taken(n) {
        n += 1;
    }
    let text = format!("Baseline {n} \u{b7} {}", format_time(now));
    Label::parse(text).unwrap_or_else(|_| Label::parse("Baseline").expect("valid label"))
}

/// Duration, readable: `42 s`, `3 min 05 s`.
pub fn format_elapsed(d: Duration) -> String {
    let s = d.as_secs();
    if s < 60 {
        format!("{s} s")
    } else {
        format!("{} min {:02} s", s / 60, s % 60)
    }
}

/// Text of a running storage operation.
pub fn operation_label(op: StorageOperation) -> &'static str {
    match op {
        StorageOperation::CreateBaseline => "Creating baseline",
        StorageOperation::RestoreBaseline => "Restoring baseline",
        StorageOperation::TakeSnapshot => "Taking snapshot",
        StorageOperation::RevertSnapshot => "Reverting snapshot",
        StorageOperation::DeleteSnapshot => "Deleting snapshot",
    }
}

/// Plain-language explanation of a failed baseline operation.
pub fn error_text(op: &BaselineOp, f: &Failure) -> String {
    let what = match op {
        BaselineOp::Create { .. } => "The baseline was not created",
        BaselineOp::Restore(_) => "The baseline was not restored",
        BaselineOp::Delete(_) => "The baseline was not deleted",
    };
    let Some(code) = f.code else {
        // Connection or protocol problem: the supervisor's own words.
        return format!("{what}: {}.", f.message);
    };
    let detail = |k: &str| f.details.get(k).and_then(|v| v.parse::<u64>().ok());
    let msg = f.message.to_ascii_lowercase();
    match (code, f.reason()) {
        (ErrorCode::StateConflict, Some("unclean_shutdown")) => format!(
            "{what}: the VM was not shut down cleanly last time (forced stop, Emergency Stop, crash or supervisor restart). Shut it down from the guest and try again, or confirm a baseline marked Not verified."
        ),
        (ErrorCode::StateConflict, Some("baseline_referenced")) => format!(
            "{what}: it is in use, the VM's current state is built on it. Restore another baseline first."
        ),
        (ErrorCode::StateConflict, Some("baseline_protected")) => format!(
            "{what}: it is protected (it belongs to an agent session) and cannot be deleted."
        ),
        (ErrorCode::StateConflict, Some("integrity")) => format!(
            "{what}: its files were changed or are missing on the host, so LightVM will not use it. Restore another baseline, or delete this one."
        ),
        (ErrorCode::StateConflict, _) if msg.contains("emergency stop") => format!(
            "{what}: cancelled by the Emergency Stop. Nothing was changed, the VM is as it was."
        ),
        (ErrorCode::StateConflict, _) if msg.contains("shutting down") => format!(
            "{what}: cancelled because the supervisor is shutting down. Nothing was changed."
        ),
        (ErrorCode::StateConflict, _) if msg.contains("no disk yet") => format!(
            "{what}: the VM has no disk yet. Start it once and install the system, then create a baseline."
        ),
        (ErrorCode::StateConflict, _) if f.details.contains_key("state") => {
            format!("{what}: the VM must be stopped. Stop it and try again.")
        }
        (ErrorCode::StateConflict, _) => format!("{what}: {}.", f.message),
        (ErrorCode::VmBusy, _) => format!(
            "{what}: the VM is busy (a start, a stop or another baseline operation is in progress, or one of its disks is open in another program). Try again when it is free."
        ),
        (ErrorCode::ResourceLimit, _) => match (
            detail("needed_bytes"),
            detail("free_bytes"),
            detail("budget_gib"),
        ) {
            (needed, _, Some(budget)) => format!(
                "{what}: it would exceed the VM's storage budget of {budget} GiB{}. Delete older baselines or raise the budget in Edit.",
                needed.map_or_else(String::new, |n| format!(
                    " (it needs about {})",
                    format_bytes(n)
                ))
            ),
            (Some(needed), Some(free), None) => format!(
                "{what}: not enough free space on the catalog drive. It needs about {}, {} is free and LightVM keeps 1 GiB in reserve.",
                format_bytes(needed),
                format_bytes(free)
            ),
            _ => format!("{what}: not enough storage ({}).", f.message),
        },
        (ErrorCode::Unsupported, _) => format!(
            "{what}: this supervisor cannot handle baselines (the QEMU disk image tool is missing). Check the QEMU folder in Settings."
        ),
        (ErrorCode::NotFound, _) => format!("{what}: the VM or the baseline no longer exists."),
        (ErrorCode::InfrastructureError, _) => format!(
            "{what}: the disk image tool or the host storage failed ({}). Nothing was changed.",
            f.message
        ),
        (ErrorCode::Unauthenticated, _) => format!(
            "{what}: the connection to the supervisor was closed during the operation. Nothing was changed."
        ),
        (ErrorCode::PermissionDenied, _) => {
            format!("{what}: this connection is not allowed to manage baselines.")
        }
        _ => format!("{what}: {}.", f.message),
    }
}

/// Why baseline changes are not possible right now, if they are not.
pub fn blocked_reason(env: &BaselinesEnv<'_>) -> Option<&'static str> {
    let v = env.vm;
    if !env.active {
        Some("The supervisor is not connected")
    } else if !env.available {
        Some("Baselines are not available: the supervisor has no QEMU disk image tool")
    } else if v.baselines.operation.is_some() {
        Some("A baseline operation is in progress on this VM")
    } else if env.any_pending {
        Some("Another baseline operation is in progress")
    } else if v.state != VmState::Stopped {
        Some("Stop the VM first: baselines are created and restored with the VM off")
    } else {
        None
    }
}

/// Why this baseline cannot be deleted, if it cannot.
pub fn delete_refusal(b: &BaselineSummary) -> Option<&'static str> {
    if b.protected {
        Some("Protected: it belongs to an agent session and cannot be deleted")
    } else if b.current {
        Some("The VM's current state is built on this baseline: restore another one first")
    } else if b.in_use {
        Some("In use by the VM: stop it or restore another baseline first")
    } else {
        None
    }
}

/// Label of a baseline of the list, if known.
pub fn label_of(list: Option<&BaselineList>, id: BaselineId) -> Option<&str> {
    list?
        .items
        .iter()
        .find(|b| b.baseline_id == id)
        .map(|b| b.label.as_str())
}

/// One line on the VM's current state and its baselines, for the
/// Dashboard row (`None` when the VM has no baseline and no operation).
pub fn dashboard_line(v: &VmSummary, list: Option<&BaselineList>) -> Option<String> {
    let b = &v.baselines;
    let mut parts = Vec::new();
    if let Some(id) = b.current {
        parts.push(match label_of(list, id) {
            Some(l) => format!("On baseline \u{201c}{l}\u{201d}"),
            None => "On a baseline".to_owned(),
        });
        parts.push(format!(
            "{} of changes since the restore",
            format_bytes(b.overlay_bytes)
        ));
    }
    if b.count > 0 {
        parts.push(format!(
            "{} {} ({})",
            b.count,
            if b.count == 1 {
                "baseline"
            } else {
                "baselines"
            },
            format_bytes(b.bytes)
        ));
    }
    (!parts.is_empty()).then(|| parts.join(" \u{b7} "))
}

fn button(
    ui: &mut egui::Ui,
    enabled: bool,
    b: egui::Button<'_>,
    name: &str,
    hover: &str,
) -> egui::Response {
    let r = ui
        .add_enabled(enabled, b)
        .on_hover_text(hover)
        .on_disabled_hover_text(hover);
    theme::accessible_name(&r, WidgetType::Button, name);
    r
}

/// Baselines page of a VM.
pub fn baselines_ui(ui: &mut egui::Ui, env: &BaselinesEnv<'_>) -> Option<BaselineAction> {
    let p = theme::Palette::of(ui);
    let v = env.vm;
    let name = v.name.as_str();
    let mut choice = None;
    let blocked = blocked_reason(env);

    theme::page_header(ui, &format!("Baselines \u{b7} {name}"), DESCRIPTION, |ui| {
        let stop = theme::danger(ui, "Emergency Stop");
        if ui
            .add_enabled(env.active, stop)
            .on_hover_text(
                "Immediately terminates all VMs and cancels a running baseline operation",
            )
            .clicked()
        {
            choice = Some(BaselineAction::EmergencyStop);
        }
        let create_hover = blocked
            .unwrap_or("Copy the VM's disk and UEFI variables into a new read-only baseline");
        if button(
            ui,
            blocked.is_none(),
            theme::primary(ui, "Create baseline…"),
            &format!("Create a baseline of {name}"),
            create_hover,
        )
        .clicked()
        {
            choice = Some(BaselineAction::Create);
        }
        if ui
            .add_enabled(env.active, egui::Button::new("Refresh"))
            .clicked()
        {
            choice = Some(BaselineAction::Refresh);
        }
        let back = ui.add(egui::Button::new("Back"));
        theme::accessible_name(&back, WidgetType::Button, "Back to the Dashboard");
        if back.clicked() {
            choice = Some(BaselineAction::Back);
        }
    });

    progress_or_outcome(ui, env);

    // Summary of the current state.
    theme::card(ui, |ui| {
        let caption = |ui: &mut egui::Ui, t: &str| {
            ui.label(egui::RichText::new(t).small().color(p.text_weak));
        };
        egui::Grid::new("lightvm_baseline_summary")
            .num_columns(4)
            .min_col_width(120.0)
            .spacing([24.0, 4.0])
            .show(ui, |ui| {
                caption(ui, "VM state");
                caption(ui, "Current state");
                caption(ui, "Changes since the restore");
                caption(ui, "Baselines");
                ui.end_row();
                let (state, tone) = vm_state(v.state);
                match v.baselines.operation {
                    Some(op) => theme::pill(ui, operation_label(op), Tone::Warning),
                    None => theme::pill(ui, state, tone),
                };
                match v.baselines.current {
                    Some(id) => {
                        let l = label_of(env.list, id).unwrap_or("a baseline");
                        ui.scope(|ui| {
                            // One line; a long label is shortened (full
                            // text in the list below).
                            ui.set_max_width(340.0);
                            ui.add(
                                egui::Label::new(format!(
                                    "Running on baseline \u{201c}{l}\u{201d}"
                                ))
                                .truncate(),
                            )
                            .on_hover_text(
                                "The VM writes to an overlay of this baseline; the baseline itself never changes",
                            );
                        });
                        ui.label(format_bytes(v.baselines.overlay_bytes));
                    }
                    None => {
                        ui.label("Standalone disk")
                            .on_hover_text("No baseline was ever restored on this VM");
                        ui.label("\u{2014}");
                    }
                }
                if v.baselines.count == 0 {
                    ui.label("None");
                } else {
                    ui.label(format!(
                        "{} \u{b7} {}",
                        v.baselines.count,
                        format_bytes(v.baselines.bytes)
                    ));
                }
                ui.end_row();
            });
    });
    if let Some(r) = blocked
        && v.baselines.operation.is_none()
        && !env.any_pending
    {
        ui.add_space(8.0);
        theme::notice(ui, &format!("{r}."), Tone::Neutral);
    }

    ui.add_space(18.0);
    theme::group_title(ui, "Baselines");
    theme::card(ui, |ui| {
        let Some(list) = env.list else {
            loading(ui);
            return;
        };
        if let Some(e) = &list.error {
            theme::notice(
                ui,
                &format!("The list could not be read: {}", e.message),
                Tone::Danger,
            );
            if list.items.is_empty() {
                return;
            }
            ui.add_space(8.0);
        }
        if !list.loaded {
            loading(ui);
            return;
        }
        if list.items.is_empty() {
            crate::empty_state(
                ui,
                "No baselines yet.",
                "Install the system, shut the VM down from the guest, then choose Create baseline. Restoring it later brings the VM back to that state.",
            );
            return;
        }
        // Most recent first.
        for (i, b) in list.items.iter().rev().enumerate() {
            if i > 0 {
                theme::divider(ui);
            }
            ui.push_id(b.baseline_id, |ui| {
                baseline_row(ui, list, b, blocked, &mut choice);
            });
        }
    });
    choice
}

fn loading(ui: &mut egui::Ui) {
    ui.vertical_centered(|ui| {
        ui.add_space(14.0);
        ui.spinner();
        ui.label("Reading the baselines…");
        ui.add_space(14.0);
    });
}

/// Running operation (with the time since it was sent) or outcome of the
/// last one on this VM.
fn progress_or_outcome(ui: &mut egui::Ui, env: &BaselinesEnv<'_>) {
    let p = theme::Palette::of(ui);
    let v = env.vm;
    let pending = env.request.filter(|r| r.status.is_pending());
    let running = v.baselines.operation.or_else(|| {
        pending.and_then(|r| match r.op {
            BaselineOp::Create { .. } => Some(StorageOperation::CreateBaseline),
            BaselineOp::Restore(_) => Some(StorageOperation::RestoreBaseline),
            BaselineOp::Delete(_) => None,
        })
    });
    if let Some(op) = running {
        let (title, body) = match op {
            StorageOperation::CreateBaseline => (
                "Creating the baseline…",
                "LightVM copies the whole disk and the UEFI variables, then checks and hashes the copy. For a large disk this takes several minutes.",
            ),
            StorageOperation::RestoreBaseline => (
                "Restoring the baseline…",
                "LightVM verifies the baseline's integrity, then replaces the VM's current state with a fresh copy of it.",
            ),
            // A snapshot operation is shown in detail on the Snapshots page;
            // here it only occupies the VM (progress card with the generic
            // text, no outcome, because it is not a baseline operation).
            StorageOperation::TakeSnapshot => (
                "Taking a snapshot…",
                "The disk of the VM is being snapshotted.",
            ),
            StorageOperation::RevertSnapshot => (
                "Reverting the VM to a snapshot…",
                "The disk of the VM is being reverted to the saved state.",
            ),
            StorageOperation::DeleteSnapshot => (
                "Deleting a snapshot…",
                "The snapshot is being removed from the disk of the VM.",
            ),
        };
        theme::card(ui, |ui| {
            ui.horizontal(|ui| {
                ui.spinner();
                ui.label(egui::RichText::new(title).color(p.text));
                if let Some(e) = env.elapsed.filter(|e| *e >= SHOW_ELAPSED_AFTER) {
                    ui.label(
                        egui::RichText::new(format_elapsed(e))
                            .small()
                            .color(p.text_weak),
                    );
                }
            });
            ui.add(egui::Label::new(egui::RichText::new(body).small().color(p.text_weak)).wrap());
            ui.add(
                egui::Label::new(
                    egui::RichText::new(
                        "The VM cannot be started or changed meanwhile. There is no time limit; only the Emergency Stop cancels the operation, and then nothing is changed.",
                    )
                    .small()
                    .color(p.text_weak),
                )
                .wrap(),
            );
        });
        ui.add_space(12.0);
        return;
    }
    let Some(r) = env.request else { return };
    let label = |id: BaselineId| {
        label_of(env.list, id).map_or_else(
            || "the baseline".to_owned(),
            |l| format!("\u{201c}{l}\u{201d}"),
        )
    };
    let (text, tone) = match (&r.status, &r.op) {
        (RequestStatus::Done(id), BaselineOp::Create { label: l, .. }) => (
            format!(
                "Baseline \u{201c}{}\u{201d} created.",
                label_of(env.list, *id).unwrap_or(l.as_str())
            ),
            Tone::Positive,
        ),
        (RequestStatus::Done(id), BaselineOp::Restore(_)) => (
            format!(
                "Restored {}: the next start boots the guest from it, with a normal boot.",
                label(*id)
            ),
            Tone::Positive,
        ),
        (RequestStatus::Done(_), BaselineOp::Delete(_)) => {
            ("Baseline deleted.".to_owned(), Tone::Positive)
        }
        (RequestStatus::Failed(f), op) => (error_text(op, f), Tone::Danger),
        _ => return,
    };
    theme::notice(ui, &text, tone);
    ui.add_space(12.0);
}

fn baseline_row(
    ui: &mut egui::Ui,
    list: &BaselineList,
    b: &BaselineSummary,
    blocked: Option<&'static str>,
    choice: &mut Option<BaselineAction>,
) {
    let p = theme::Palette::of(ui);
    let label = b.label.as_str();
    const ACTIONS: f32 = 190.0;
    ui.horizontal(|ui| {
        ui.set_min_height(46.0);
        let left = (ui.available_width() - ACTIONS - 12.0).max(150.0);
        ui.allocate_ui_with_layout(
            egui::vec2(left, 46.0),
            egui::Layout::top_down(egui::Align::Min),
            |ui| {
                ui.set_width(left);
                ui.spacing_mut().item_spacing.y = 3.0;
                ui.horizontal_wrapped(|ui| {
                    ui.spacing_mut().item_spacing.x = 6.0;
                    ui.add(
                        egui::Label::new(egui::RichText::new(label).size(15.0).color(p.text))
                            .truncate(),
                    );
                    if b.current {
                        theme::pill(ui, "Current", Tone::Accent).on_hover_text(
                            "The VM's current state is an overlay of this baseline",
                        );
                    }
                    if b.clean_shutdown {
                        theme::pill(ui, "Verified", Tone::Positive).on_hover_text(
                            "Taken after a clean shutdown of the guest (or before any run)",
                        );
                    } else {
                        theme::pill(ui, "Not verified", Tone::Warning).on_hover_text(
                            "Taken after a forced or unobserved stop, with your consent: the disk may hold incomplete writes",
                        );
                    }
                    if b.protected {
                        theme::pill(ui, "Protected", Tone::Neutral)
                            .on_hover_text("Belongs to an agent session: it cannot be deleted");
                    }
                    if b.in_use && !b.current {
                        theme::pill(ui, "In use", Tone::Neutral)
                            .on_hover_text("Used by the VM's current run");
                    }
                });
                let mut details = vec![
                    format!("Created {}", format_time(b.created_at)),
                    format!("{} on the host", format_bytes(b.size_bytes)),
                    format!("disk {}", format_bytes(b.virtual_size_bytes)),
                ];
                if let Some(parent) = b.derived_from {
                    details.push(match label_of(Some(list), parent) {
                        Some(l) => format!("taken on \u{201c}{l}\u{201d}"),
                        None => "taken on a deleted baseline".to_owned(),
                    });
                }
                ui.add(
                    egui::Label::new(
                        egui::RichText::new(details.join(" \u{b7} "))
                            .small()
                            .color(p.text_weak),
                    )
                    .wrap(),
                );
            },
        );
        ui.allocate_ui_with_layout(
            egui::vec2(ACTIONS, 46.0),
            egui::Layout::right_to_left(egui::Align::Center),
            |ui| {
                ui.spacing_mut().item_spacing.x = 6.0;
                let refusal = delete_refusal(b);
                let delete_hover = blocked
                    .or(refusal)
                    .unwrap_or("Removes this baseline from the host (asks for confirmation)");
                if button(
                    ui,
                    blocked.is_none() && refusal.is_none(),
                    egui::Button::new(egui::RichText::new("Delete…").color(p.danger))
                        .min_size(egui::vec2(72.0, 0.0)),
                    &format!("Delete baseline {label}"),
                    delete_hover,
                )
                .clicked()
                {
                    *choice = Some(BaselineAction::Delete(b.baseline_id));
                }
                let restore_hover = blocked.unwrap_or(
                    "Discards the VM's current state and brings it back to this baseline (asks for confirmation)",
                );
                if button(
                    ui,
                    blocked.is_none(),
                    egui::Button::new("Restore…").min_size(egui::vec2(72.0, 0.0)),
                    &format!("Restore baseline {label}"),
                    restore_hover,
                )
                .clicked()
                {
                    *choice = Some(BaselineAction::Restore(b.baseline_id));
                }
            },
        );
    });
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn times_and_labels_are_readable() {
        let t = UtcTimestamp::from_unix_millis(1_791_710_000_000).unwrap();
        let s = format_time(t);
        assert!(s.ends_with(" UTC") && s.len() == 20, "{s}");
        let l = auto_label(&[], t);
        assert_eq!(l.as_str(), format!("Baseline 1 \u{b7} {s}"));
        assert_eq!(format_elapsed(Duration::from_secs(42)), "42 s");
        assert_eq!(format_elapsed(Duration::from_secs(185)), "3 min 05 s");
    }

    #[test]
    fn errors_are_explained() {
        let op = BaselineOp::Delete(BaselineId::new_v7());
        let f = Failure::coded(ErrorCode::StateConflict, "state_conflict: in use")
            .with_detail("reason", "baseline_referenced");
        assert!(error_text(&op, &f).contains("Restore another baseline first"));
        let f = Failure::coded(ErrorCode::ResourceLimit, "x")
            .with_detail("needed_bytes", "4294967296")
            .with_detail("free_bytes", "1073741824");
        let t = error_text(&op, &f);
        assert!(
            t.contains("4.0 GiB") && t.contains("1.0 GiB is free"),
            "{t}"
        );
        let f = Failure::new("supervisor connection closed");
        assert!(error_text(&op, &f).contains("supervisor connection closed"));
    }
}
